function confirmAction(title,message,action){dialog(title,`<p class="dialog-copy">${escapeHTML(message)}</p><div class="dialog-actions"><button id="cancelAction">キャンセル</button><button id="confirmAction" class="primary">実行する</button></div>`);$('cancelAction').onclick=closeDialog;$('confirmAction').onclick=()=>{closeDialog();run(action);};}
async function run(fn){try{return await fn();}catch(e){console.error(e);const errors={NotAllowedError:'マイクの利用を許可してください。ブラウザとmacOSのマイク設定を確認できます。',NotFoundError:'入力機器が見つかりません。マイクやオーディオインターフェースを接続してください。',NotReadableError:'入力機器を開けません。他のアプリの使用状況を確認してください。',OverconstrainedError:'選択した入力機器を使用できません。入力を再検出してください。'};toast(errors[e.name]||e.message||'処理を完了できませんでした');}}
function duration(){return engine.duration();}function formatTime(s){s=Math.max(0,Number.isFinite(s)?s:0);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;}
